import{_ as d,C as s,o as i,c as r,a2 as a,j as e,E as n}from"./chunks/framework.DrWxItG4.js";const b=JSON.parse('{"title":"How the client was analyzed","description":"","frontmatter":{},"headers":[],"relativePath":"guide/client-analysis.md","filePath":"guide/client-analysis.md"}'),c={name:"guide/client-analysis.md"},l={tabindex:"0"};function h(u,o,g,m,f,p){const t=s("Badge");return i(),r("div",null,[o[4]||(o[4]=a('<h1 id="how-the-client-was-analyzed" tabindex="-1">How the client was analyzed <a class="header-anchor" href="#how-the-client-was-analyzed" aria-label="Permalink to &quot;How the client was analyzed&quot;">​</a></h1><p>The client-side information on this site (the action list, the login fields, the function names and the game packets the client sends) comes from static analysis of <code>libgrowtopia.so</code> from Growtopia 5.60 (build 426, arm64). The game&#39;s own functions have no symbol names.</p><h2 id="method" tabindex="-1">Method <a class="header-anchor" href="#method" aria-label="Permalink to &quot;Method&quot;">​</a></h2><ol><li><strong>Strings → functions.</strong> Disassemble <code>.text</code> with <code>llvm-objdump</code>, find every <code>ADRP</code>+<code>ADD</code> or <code>ADR</code> that computes an address inside <code>.rodata</code>, and group those references by function. The function boundaries come from the <code>.eh_frame</code> unwind records. A function that references <code>action|drop\\n|itemID|</code> followed by <code>\\n</code> builds that message, and the order of its string references gives the field order.</li><li><strong>The send function.</strong> <code>0x157ee8c</code> is called with <code>(4, header, 0x38, extra, peer, 1)</code>: message type 4, a 56-byte header, reliable. It drops packets over 1,000,000 bytes, and appends <code>extra</code> only when header byte 12 has bit 3 set (S_EXTENDED).</li><li><strong>Game packet types.</strong> For each call to the send function (and to the four helpers that wrap it), read the byte constant stored at offset 0 of the header just before the call.</li><li><strong>Game packets the client receives.</strong> The incoming handler (<code>0x1373e20</code>) reads the type byte, sends anything above <code>0x2d</code> to a do-nothing default (<code>0x1376388</code>), and otherwise jumps through a table of 46 16-bit offsets at <code>0x7fae44</code>. 34 types have their own handler, so the official server sends them. The other 12 (<code>0x02</code>, <code>0x07</code>, <code>0x0a</code>, <code>0x0b</code>, <code>0x15</code>, <code>0x17</code>, <code>0x18</code>, <code>0x19</code>, <code>0x1a</code>, <code>0x1e</code>, <code>0x2b</code>, <code>0x2c</code>) go to the default: the client ignores them, and most are types it only sends. The switch and every handler it reaches were then decompiled with Ghidra 12.1.4 (see below). The <strong>What the client does with it</strong> section on each packet page is written from that decompiled code: the fields it reads, the sub-commands it branches on, the strings and sounds it uses, and a cleaned-up copy of the handler.</li><li><strong>Packet names.</strong> A static initializer (<code>0x108ea9c</code>) registers the client&#39;s own names for the types, <code>NET_GAME_PACKET_STATE</code> through <code>NET_GAME_PACKET_ON_STEP_ON_TILE_MOD</code> (0x2e). The packet pages use them. They differ from GrowServer&#39;s list from 0x19 on, for example 0x28 <code>FTUE_SET_ITEM_TO_QUICK_INVENTORY</code> and 0x2d <code>SET_EXTRA_MODS</code>. 0x08-0x0a aren&#39;t in the table; their names come from the servers.</li><li><strong>Server functions.</strong> Three functions register a handler per name: <code>0x135e25c</code> (GameLogic, global functions), <code>0x12ecb2c</code> (NetAvatar, functions about one player) and <code>0x1ba1ec8</code> (login and menu screens, <code>std::function</code> lambdas added as extra listeners on GameLogic&#39;s functions). The world screen (<code>0x1bff3ec</code>) adds <code>OnDialogRequest</code> and <code>OnDialogRequestRML</code> the same way, and 19 more screens and controllers add their own names through <code>0x1be9ae8</code> while they are open (mail, auctions, dungeons, wardrobe...). That gives 215 names. Each handler was decompiled, and each function page&#39;s <strong>What the client does with it</strong> section is written from it. Handlers get a list of the arguments only: the client copies variants 1–6 into a new list, so the first argument is the handler&#39;s slot 0. Global functions run only when the header <code>netID</code> is -1; player functions run on the avatar with that <code>netID</code>.</li><li><strong><code>proto</code>.</strong> Many handlers check <code>app+0xc08</code>, the <code>proto|</code> value from the <a href="/gtps-guide/functions/OnSuperMainStartAcceptLogonHrdxs47254722215a">OnSuperMainStartAcceptLogon…</a> settings (default 15), to choose between old and new formats. Function pages say which value they need.</li></ol><h2 id="decompiling-with-ghidra" tabindex="-1">Decompiling with Ghidra <a class="header-anchor" href="#decompiling-with-ghidra" aria-label="Permalink to &quot;Decompiling with Ghidra&quot;">​</a></h2><p>Two settings matter, and without them Ghidra seems to time out on everything:</p><ul><li><strong>Image base 0.</strong> Ghidra loads an arm64 <code>.so</code> at <code>0x100000</code>, so the addresses on this site (which come from <code>llvm-objdump</code>, base 0) point 1 MiB into the wrong code. Rebase the program to 0 (<code>currentProgram.setImageBase(toAddr(0), true)</code>) before using any address from here.</li><li><strong>Function bounds from <code>.eh_frame</code>.</strong> Ghidra&#39;s own analysis merges and splits many functions. Recreating every function from the 86,682 <code>.eh_frame</code> ranges gives correct bodies, so tail calls end where they should.</li></ul><p>With both, the whole 12 KB switch decompiles in about 45 seconds and most handlers in under one, with the timeout off (<code>decompileFunction(f, 0, monitor)</code>).</p><p>The pseudo-C on the packet pages is cleaned up by hand: helper functions get descriptive names (<code>GetTile</code>, <code>PlaySound</code>, ...), <code>std::string</code> and stack-protector code is left out, and string literals that Ghidra drops from inlined <code>std::string::append</code> calls are filled back in from the <code>.rodata</code> references. Functions nobody has named keep their address (<code>sub_14c86b8</code>).</p><h2 id="confidence" tabindex="-1">Confidence <a class="header-anchor" href="#confidence" aria-label="Permalink to &quot;Confidence&quot;">​</a></h2>',10)),e("table",l,[o[3]||(o[3]=e("thead",null,[e("tr",null,[e("th",null,"Badge"),e("th",null,"Meaning")])],-1)),e("tbody",null,[e("tr",null,[e("td",null,[n(t,{type:"tip",text:"confirmed"})]),o[0]||(o[0]=e("td",null,"gurotopia sends or handles it, and the client code agrees",-1))]),e("tr",null,[e("td",null,[n(t,{type:"warning",text:"inferred"})]),o[1]||(o[1]=e("td",null,"only seen in the client; the meaning is a reasonable guess",-1))]),e("tr",null,[e("td",null,[n(t,{type:"danger",text:"unknown"})]),o[2]||(o[2]=e("td",null,"the client sends it, but what it means isn't known yet",-1))])])]),o[5]||(o[5]=a('<h2 id="known-gaps" tabindex="-1">Known gaps <a class="header-anchor" href="#known-gaps" aria-label="Permalink to &quot;Known gaps&quot;">​</a></h2><ul><li><strong>Short names.</strong> <code>OnSpawn</code>, <code>OnRemove</code>, <code>OnSetPos</code>, <code>OnSetBux</code> and <code>OnKilled</code> aren&#39;t in <code>.rodata</code>. Names of up to 22 characters fit libc++&#39;s short-string buffer, so the compiler writes them with immediate <code>mov</code>/<code>str</code> instructions (case 0x04 builds <code>OnInitNewWorld</code> this way). A search for the text won&#39;t find them.</li><li><strong>Meanings of stored values.</strong> Some handlers only store a value (a cosmetic&#39;s state, a flag). Where nothing that reads it was found, the page says so instead of guessing.</li></ul><p>The best way to settle the open questions is to log what the Windows app sends to your server while playing, through a <a href="/gtps-guide/guide/relay">relay</a> or by printing in <code>receive()</code>.</p>',3))])}const y=d(c,[["render",h]]);export{b as __pageData,y as default};
